'use strict';
const workforceRoles={teacher:'Professor',monitor:'Monitor'},workforceDrafts=new Map();
async function monitorList(){const {monitors}=await api('/monitors');$('monitor-list').replaceChildren();for(const m of monitors){const b=el('button',m.name+' · '+(m.active?'Ativo':'Inativo'),{class:'secondary registration-row'});if(m.scope_readonly){b.disabled=true;b.textContent+=' · Cadastro compartilhado: administração geral';}else b.addEventListener('click',()=>monitorForm(m));$('monitor-list').append(b)}if(!monitors.length)$('monitor-list').append(el('p','Cadastre os monitores para incluí-los na chamada da equipe.'))}
function monitorForm(m={version:0,active:true,units:[]}){
 const box=$('monitor-detail');box.hidden=false;box.replaceChildren(el('h3',m.id?'Editar monitor':'Cadastrar monitor'),el('p','Cadastro administrativo para controle de frequência. O monitor não recebe acesso ao painel por este cadastro.'));
 const form=el('form');field(form,'Nome completo do monitor','name',m.name).required=true;field(form,'Email do monitor (opcional)','email',m.email,{type:'email'});field(form,'Telefone / WhatsApp com DDD','phone',m.phone,{type:'tel'}).required=true;
 const units=el('fieldset');units.append(el('legend','Núcleos de atuação'));for(const [u,label]of Object.entries(scopeUnitNames())){const line=el('label',undefined,{class:'check-label'}),input=el('input',undefined,{type:'checkbox',name:'units',value:u});input.checked=m.units.includes(u);line.append(input,document.createTextNode(label));units.append(line)}form.append(units);field(form,'Situação do monitor','active',String(m.active),{options:{true:'Ativo',false:'Inativo'}});longField(form,'Observações administrativas (opcional, sem dados de saúde)','notes',m.notes||'').maxLength=1000;
 form.append(el('button','Salvar monitor'));form.addEventListener('submit',action(async()=>{const data=new FormData(form),p=await api('/monitors'+(m.id?'/'+m.id:''),{method:m.id?'PATCH':'POST',data:{...Object.fromEntries(data),units:data.getAll('units'),active:data.get('active')==='true',version:m.version}});await monitorList();monitorForm(p.monitor);notice(p.message)}));box.append(form);box.scrollIntoView({block:'start'});
}
async function workforceList(){const unit=$('workforce-unit').value,{sessions}=await api('/workforce-sessions?unit='+unit);$('workforce-list').replaceChildren();for(const s of sessions){const b=el('button',s.day.split('-').reverse().join('/')+' · '+s.start_time+'–'+s.end_time+' · '+s.label,{class:'secondary registration-row'});b.addEventListener('click',action(()=>workforceDetail(s.id)));$('workforce-list').append(b)}if(!sessions.length)$('workforce-list').append(el('p','Nenhuma chamada da equipe aberta neste núcleo.'))}
async function workforceOptions(){const unit=$('workforce-unit').value,[{groups},{people}]=await Promise.all([api('/groups?unit='+unit),api('/workforce?unit='+unit)]),select=$('workforce-group');select.replaceChildren(el('option','Selecione a turma',{value:''}));for(const g of groups.filter(g=>g.active))select.append(el('option',g.label+' · '+g.start_time+'–'+g.end_time,{value:g.id}));const box=$('workforce-people');box.replaceChildren(el('legend','Equipe prevista para esta aula'));for(const p of people){const line=el('label',undefined,{class:'check-label'}),input=el('input',undefined,{type:'checkbox',name:'people',value:p.id});line.append(input,document.createTextNode(p.name+' · '+workforceRoles[p.role]));box.append(line)}if(!people.length)box.append(el('p','Cadastre os monitores ou confira o cadastro e os núcleos dos professores primeiro.'));await workforceList()}
async function workforceDetail(id){
 const {lesson,people}=await api('/workforce-sessions/'+id),box=$('workforce-detail');box.hidden=false;box.replaceChildren(el('h3','Frequência da equipe · '+lesson.day.split('-').reverse().join('/')),el('p',classUnits[lesson.unit]+' · '+lesson.label+' · '+lesson.start_time+'–'+lesson.end_time),el('p','Marque cada integrante e salve ao final. Não marcado não conta como falta. A lista preserva os nomes registrados na abertura desta aula.'));
 const draft=workforceDrafts.get(id)||new Map(people.map(p=>[p.person_key,{status:p.status,note:p.note,version:p.version}]));workforceDrafts.set(id,draft);const form=el('form'),summary=el('p','',{role:'status','aria-live':'polite'}),savebar=el('div',undefined,{class:'save-call'}),save=el('button','Salvar frequência da equipe');
 const changed=()=>people.filter(p=>draft.get(p.person_key).status!==p.status||draft.get(p.person_key).note!==p.note);
 const update=()=>{summary.textContent=Object.entries(attendanceNames).map(([k,v])=>v+': '+people.filter(p=>draft.get(p.person_key).status===k).length).join(' · ');save.textContent='Salvar equipe ('+changed().length+' alterações)'};
 for(const p of people){const line=el('fieldset',undefined,{class:'attendance-person'});line.append(el('legend',p.name),el('small',workforceRoles[p.role]));const buttons=el('div',undefined,{class:'attendance-options'});for(const [status,label]of Object.entries(attendanceNames)){const b=el('button',status==='unmarked'?'Limpar':label,{type:'button',class:'attendance-choice','aria-pressed':String(draft.get(p.person_key).status===status),'data-status':status});b.addEventListener('click',()=>{draft.get(p.person_key).status=status;for(const other of buttons.children)other.setAttribute('aria-pressed',String(other===b));update()});buttons.append(b)}line.append(buttons);const more=el('details');more.append(el('summary','Observação ou justificativa'));const note=longField(more,'Observação administrativa (opcional)','note-'+p.person_key,draft.get(p.person_key).note);note.maxLength=500;note.addEventListener('input',()=>{draft.get(p.person_key).note=note.value;update()});line.append(more);form.append(line)}
 update();savebar.append(summary,save);form.append(savebar);form.addEventListener('submit',action(async()=>{const rows=changed().map(p=>({id:p.person_key,...draft.get(p.person_key)}));if(!rows.length){notice('Nenhuma marcação alterada.');return}const r=await api('/workforce-sessions/'+id,{method:'POST',data:{rows}});workforceDrafts.delete(id);await workforceDetail(id);notice(r.message);$('workforce-detail').prepend(el('p',r.message,{class:'form-success',role:'status'}))}));box.append(form);
 const history=el('details');history.append(el('summary','Histórico das marcações'));const body=el('div');history.append(body);history.addEventListener('toggle',()=>{if(history.open&&!body.children.length)action(async()=>{const {history:rows}=await api('/workforce-sessions/'+id+'/history');for(const r of rows){const person=people.find(p=>p.person_key===r.person_key);body.append(el('p',(person?.name||r.person_key)+' · '+attendanceNames[r.previous_status]+' → '+attendanceNames[r.status]+' · '+r.author_email+' · '+new Date(r.created_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})));if(r.note)body.append(el('p',r.note))}if(!rows.length)body.append(el('p','Nenhuma marcação salva ainda.'))})()});box.append(history);box.scrollIntoView({block:'start'});
}
function setupWorkforce(){
 if(!$('monitors-area')){const area=el('section',undefined,{id:'monitors-area'});$('team-area').before(area);area.append(el('h2','Monitores'),el('button','Cadastrar monitor',{id:'monitor-new'}),el('div',undefined,{id:'monitor-list'}),el('section',undefined,{id:'monitor-detail',hidden:''}));$('monitor-new').addEventListener('click',()=>monitorForm())}
 if($('workforce-area'))return;const area=el('section',undefined,{id:'workforce-area'});$('team-area').before(area);area.append(el('h2','Frequência de professores e monitores'),el('p','A secretaria e os administradores registram esta chamada. Escolha a aula e selecione quem estava previsto na equipe; depois marque a presença. Este controle é separado da frequência dos alunos.'));
 const form=el('form');field(form,'Núcleo da equipe','unit','amavale',{options:scopeUnitNames(),htmlId:'workforce-unit'});field(form,'Turma e horário da equipe','group_id','',{options:{},htmlId:'workforce-group'}).required=true;field(form,'Data da aula da equipe','day',todayBR(),{type:'date',max:todayBR()}).required=true;form.append(el('fieldset',undefined,{id:'workforce-people'}),el('button','Abrir chamada da equipe'));area.append(form,el('section',undefined,{id:'workforce-detail',hidden:''}),el('h3','Chamadas da equipe já abertas'),el('div',undefined,{id:'workforce-list'}));$('workforce-unit').addEventListener('change',action(async()=>{$('workforce-detail').hidden=true;await workforceOptions()}));form.addEventListener('submit',action(async()=>{const f=new FormData(form),r=await api('/workforce-sessions',{method:'POST',data:{group_id:f.get('group_id'),day:f.get('day'),people:f.getAll('people')}});await workforceList();await workforceDetail(r.lesson.id)}));
 const exportForm=el('form');exportForm.append(el('h3','Exportar frequência da equipe'));field(exportForm,'Data inicial','from',todayBR().slice(0,7)+'-01',{type:'date'}).required=true;field(exportForm,'Data final','to',todayBR(),{type:'date'}).required=true;exportForm.append(el('button','Baixar frequência da equipe CSV'));exportForm.addEventListener('submit',action(async()=>{const query=new URLSearchParams({...Object.fromEntries(new FormData(exportForm)),unit:$('workforce-unit').value});download(await api('/workforce.csv?'+query,{blob:true}),'frequencia-professores-monitores.csv')}));area.append(exportForm);
}
document.addEventListener('portal:loaded',action(async()=>{if(['admin','secretary'].includes(me.role)){setupWorkforce();$('monitors-area').hidden=false;$('workforce-area').hidden=false;await Promise.all([monitorList(),workforceOptions()])}else for(const id of ['monitors-area','workforce-area'])if($(id))$(id).hidden=true}));
document.addEventListener('portal:logout',()=>{for(const id of ['monitors-area','workforce-area'])$(id)?.remove();workforceDrafts.clear()});
